def find_base_blocks():
    import itertools
    v = 13
    k = 3
    lam = 2

    # All possible blocks of size 3 containing 0
    blocks = []
    for i in range(1, v):
        for j in range(i+1, v):
            blocks.append((0, i, j))

    # We need to choose 4 blocks
    for combo in itertools.combinations(blocks, 4):
        diffs = [0] * v
        for block in combo:
            for x in block:
                for y in block:
                    if x != y:
                        diffs[(x - y) % v] += 1
        if all(diffs[i] == lam for i in range(1, v)):
            return combo
    return None

print(find_base_blocks())

def generate_matrix():
    v = 13
    b = 52
    base_blocks = [(0, 1, 2), (0, 2, 6), (0, 3, 7), (0, 3, 8)]
    blocks = []
    for bb in base_blocks:
        for i in range(v):
            blocks.append([(x + i) % v for x in bb])

    matrix = [[0]*b for _ in range(v)]
    for j, block in enumerate(blocks):
        for point in block:
            matrix[point][j] = 1

    # Verify
    for row in matrix:
        assert sum(row) == 12
    for col in range(b):
        assert sum(matrix[i][col] for i in range(v)) == 3

    for i in range(v):
        for j in range(i+1, v):
            dot = sum(matrix[i][k] * matrix[j][k] for k in range(b))
            assert dot == 2

    flat = [x for row in matrix for x in row]
    print(flat)

generate_matrix()
